// SVG is generated by a third party. Render and download only a static, self-contained document.
export function assertSafeSvg(xml, Parser = DOMParser) {
  if (typeof xml !== 'string' || xml.length > 10 * 1024 * 1024 || /<!DOCTYPE|<!ENTITY/i.test(xml)) throw new Error('SVG 格式不安全，無法預覽或保存');
  const doc = new Parser().parseFromString(xml, 'image/svg+xml');
  if (doc.querySelector('parsererror') || doc.documentElement?.localName !== 'svg') throw new Error('SVG 格式無法解析');
  const forbidden = new Set(['script', 'foreignobject', 'iframe', 'object', 'embed', 'style', 'link', 'animate', 'animatemotion', 'animatetransform', 'set']);
  for (const el of doc.querySelectorAll('*')) {
    if (forbidden.has(el.localName.toLowerCase())) throw new Error('SVG 包含不支援的動態內容');
    for (const attr of el.attributes) {
      const name = attr.localName.toLowerCase(), value = attr.value.trim();
      if (attr.name === 'xmlns' || attr.name.startsWith('xmlns:')) {
        if (!['http://www.w3.org/2000/svg', 'http://www.w3.org/1999/xlink'].includes(value)) throw new Error('SVG 包含不支援的命名空間');
        continue;
      }
      if (name.startsWith('on') || name === 'src' || name === 'base' || /@import|javascript:|data:|https?:|\/\//i.test(value) && name !== 'xmlns') throw new Error('SVG 包含不支援的外部內容');
      if (name === 'href' && value && !value.startsWith('#')) throw new Error('SVG 包含不支援的外部連結');
      for (const match of value.matchAll(/url\(\s*([^)]*)\s*\)/gi)) if (!/^['"]?#[\w:.-]+['"]?$/.test(match[1].trim())) throw new Error('SVG 包含不支援的外部資源');
    }
  }
  return xml;
}
